// Actual UI file upload and acceptance. Fresh storage; static-origin GET allowlist only.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {webkit,chromium}=require('playwright');
const {cases,workbook,active}=require('./zff-import-test.cjs'),seed=require('./ui-fixture.cjs');
const url=process.env.PREVIEW_URL;if(!url)throw Error('PREVIEW_URL required');
const origin=new URL(url).origin,out=process.env.ZFF_OUTPUT||'zff-audit-output';fs.mkdirSync(out,{recursive:true});
const matrix={},evidence={},screenshots=[],errors=[];let blocked=0,allowedWrites=0;
function check(k,ok,data){matrix[k]=ok?'PASS':'FAIL';if(data!==undefined)evidence[k]=data;console.log(k+' '+matrix[k]+(ok?'':' '+JSON.stringify(data)));}
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
async function run(b,device,width,height){const prefix=device+'.',folder=path.join(out,device);fs.mkdirSync(folder,{recursive:true});
 const ctx=await b.newContext({viewport:{width,height},isMobile:device!=='desktop',hasTouch:device!=='desktop',locale:'de-CH',timezoneId:'Europe/Zurich',reducedMotion:'reduce',serviceWorkers:'block'});
 await ctx.route('**/*',r=>{const q=r.request(),u=new URL(q.url());if(u.origin!==origin||!['GET','HEAD'].includes(q.method())||u.pathname.startsWith('/api/')){blocked++;return r.abort();}return r.continue();});
 await ctx.addInitScript(({source})=>{if(!sessionStorage.getItem('zff-fixture-seeded')){(0,eval)('('+source+')')();sessionStorage.setItem('zff-fixture-seeded','yes');}},{source:seed.toString()});
 const p=await ctx.newPage();p.setDefaultTimeout(20000);p.on('pageerror',e=>errors.push({device,error:e.message}));
 async function shot(name){await p.evaluate(()=>document.fonts.ready);const file=path.join(folder,name+'.png');await p.screenshot({path:file,animations:'disabled'});screenshots.push({file,url,device,width,height});check(prefix+'overflow.'+name,await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));}
 async function choose(role){await p.locator('.role-selection [data-role='+role+']').click();await p.locator('.app-shell').waitFor();await p.locator('.work-area-entry-transition').waitFor({state:'detached'});}
 async function upload(){await p.locator('input[type=file]').first().setInputFiles({name:'synthetic-zff-mews.xlsx',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',buffer:workbook()});await p.locator('.import-modal').waitFor();}
 try{
  const response=await p.goto(url,{waitUntil:'domcontentloaded'});check(prefix+'index-live-reachable',response.ok()&&new URL(p.url()).pathname==='/index-live.html',{status:response.status(),url:p.url()});await p.locator('.role-selection').waitFor();await shot('01-bereichswahl');
  const script=await p.locator('script[src*="0nkyeaxka~cd7-meili-v9.js"]').first().getAttribute('src');const scriptUrl=new URL(script,url);if(scriptUrl.origin!==origin)throw Error('Unexpected parser asset origin');const loaded=await ctx.request.get(scriptUrl.href),bytes=await loaded.body();check(prefix+'actual-active-parser',loaded.ok()&&sha(bytes)===sha(fs.readFileSync(active)),{url:scriptUrl.href,sha256:sha(bytes),expected:sha(fs.readFileSync(active))});
  await choose('reception');check(prefix+'reception-open',await p.locator('.reception-actions').isVisible());await shot('02-reception-before');const before=await p.evaluate(()=>localStorage.getItem('ambassador-breakfast-rooms'));
  await upload();const summary=await p.locator('.import-summary > span').allTextContents();const vals=await p.locator('.import-summary strong').allTextContents();const expected=[cases.filter(c=>c.included).reduce((n,c)=>n+c.people,0),cases.length,cases.reduce((n,c)=>n+c.people,0)];check(prefix+'review-sums',JSON.stringify(vals.map(Number))===JSON.stringify(expected),{summary,actual:vals,expected});
  const rows=await p.locator('.import-list > div').evaluateAll(es=>es.map(e=>({room:Number(e.querySelector('strong').textContent),guest:e.querySelector('span').textContent,people:Number(e.querySelector('small').textContent.match(/^\d+/)[0]),included:e.classList.contains('included')})));
  for(const t of cases){const r=rows.find(r=>r.room===t.room);check(prefix+'review.'+t.id,!!r&&r.included===t.included&&r.people===t.people&&r.guest.includes(t.guest),r);}
  await shot('03-import-review-top');await p.locator('.import-modal > .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);await shot('04-import-review-bottom');await p.locator('.import-modal').getByRole('button',{name:'Abbrechen',exact:true}).click();check(prefix+'cancel-keeps-existing-local-list',await p.evaluate(()=>localStorage.getItem('ambassador-breakfast-rooms'))===before);
  await p.locator('input[type=file]').first().setInputFiles([]);await upload();await p.locator('.import-modal').getByRole('button',{name:'Liste übernehmen',exact:true}).click();await p.locator('.import-modal').waitFor({state:'detached'});await p.locator('.success-overlay').waitFor({state:'detached'});
  const state=await p.evaluate(()=>JSON.parse(localStorage.getItem('ambassador-breakfast-rooms')));for(const t of cases){const r=state.rooms.find(r=>r.room===t.room);check(prefix+'accepted.'+t.id,!!r&&r.included===t.included&&r.people===t.people&&r.arrival===t.arrival&&r.departure===t.departure,r);}
  check(prefix+'accepted-counts',state.rooms.filter(r=>r.guests.length).length===expected[1]&&state.rooms.reduce((n,r)=>n+r.people,0)===expected[2]&&state.rooms.filter(r=>r.included).reduce((n,r)=>n+r.people,0)===expected[0]);await shot('05-reception-after-import');
  await p.getByRole('button',{name:'Zimmer 20 öffnen',exact:true}).click();check(prefix+'reception-detail-included',await p.locator('.reception-view-mode').getByText('inklusive',{exact:true}).count()>0);await shot('06-reception-detail');await p.locator('.reception-view-mode .close-button').click();
  await p.getByRole('button',{name:'Zur Startseite',exact:true}).click();await p.locator('.role-selection').waitFor();await choose('service');await shot('07-service-after-import');
  const room=p.getByRole('button',{name:'Zimmer 20 öffnen',exact:true});check(prefix+'service-zff-room-included',await room.getByText('Frühstück inklusive',{exact:true}).count()>0,{text:await room.innerText()});await room.click();await p.locator('.checkin-choice-modal').waitFor();await shot('08-check-in');
  await p.locator('.checkin-choice-modal .table-picker').getByRole('button',{name:'17',exact:true}).click();await p.locator('.checkin-choice-modal .modal-actions .primary').click();await p.locator('.checkin-card').waitFor();await shot('09-success');
  const afterCheckin=await p.evaluate(()=>JSON.parse(localStorage.getItem('ambassador-breakfast-rooms')).rooms.find(r=>r.room===20));check(prefix+'check-in-unchanged',afterCheckin.included&&afterCheckin.people===2&&afterCheckin.arrivedCount===2&&afterCheckin.table==='Tisch 17',afterCheckin);
  await p.locator('.checkin-card').getByRole('button',{name:'Verstanden',exact:true}).click();await p.getByRole('button',{name:'Menü öffnen',exact:true}).click();check(prefix+'service-menu',await p.locator('[data-menu-action=Statistik]').count()>0);await shot('10-service-menu');
 }catch(e){check(prefix+'scenario',false,{message:String(e)});await p.screenshot({path:path.join(folder,'FAIL.png')}).catch(()=>{});}finally{await ctx.close();}
}
(async()=>{const engine=process.env.ZFF_ENGINE||'webkit';let b;if(engine==='chromium'&&process.env.CHROMIUM_HELPER){const helper=(await import(process.env.CHROMIUM_HELPER)).default;b=await chromium.launch({executablePath:await helper.executablePath(),args:helper.args});}else b=await ({webkit,chromium}[engine]).launch();try{for(const v of [['iphone',390,844],['ipad',1024,1366],['desktop',1440,900]])await run(b,...v);}finally{await b.close();}check('runtime-errors',errors.length===0,errors);check('external-and-all-write-requests-blocked',allowedWrites===0,{blocked,allowedWrites,policy:'New context, service workers blocked, only exact tested origin GET/HEAD, no API requests; all other requests aborted before network.'});const result={url,commit:process.env.SOURCE_SHA,engine,matrix,evidence,screenshots,errors,pass:Object.values(matrix).filter(v=>v==='PASS').length,fail:Object.values(matrix).filter(v=>v==='FAIL').length,physicalSafari:'NOT_TESTED'};fs.writeFileSync(path.join(out,'browser-results.json'),JSON.stringify(result,null,2));console.log(JSON.stringify({pass:result.pass,fail:result.fail}));if(result.fail)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1;});
